import test from 'node:test';
import assert from 'node:assert/strict';
import {createApp} from '../src/app.js';
import {insightScenario} from './insight-helpers.js';
import {persistActivity} from '../src/modules/insight/activity.js';
import {runDueDigests,startDigestService} from '../src/modules/insight/digest-runner.js';
import {preferences} from '../src/modules/insight/notifications.js';
const plus=(at,ms)=>new Date(Date.parse(at)+ms).toISOString();
function seed(s,count,{userId=s.user.id,projectId=s.project.id,reason='watching',relation}={}) {
  const {ctx}=s.server;
  ctx.transaction(()=>{
    for(let n=0;n<count;n++) {
      const event={id:ctx.id(),orgId:s.org.id,projectId,actorId:s.memberUser.id,entityType:relation?'relation':'issue',entityId:s.issue.id,action:'updated',after:relation??{id:s.issue.id,title:'Digest row '+n},time:ctx.now()};
      persistActivity(ctx,event);
      ctx.db.prepare('INSERT INTO notifications(id,user_id,org_id,project_id,activity_id,reason,created_at) VALUES (?,?,?,?,?,?,?)')
        .run(ctx.id(),userId,s.org.id,projectId,event.id,reason,event.time);
    }
  });
}
async function enable(s,options={}) {
  const result=await s.api('PATCH','/notification-preferences',{orgId:s.org.id,digestFrequency:'15-minute',...options});
  assert.equal(result.status,200,JSON.stringify(result.data));return result.data.preferences.digestSchedule.nextRunAt;
}
function digests(ctx){return ctx.db.prepare("SELECT * FROM outbox WHERE kind='digest' ORDER BY created_at,id").all();}
test('manual is persisted default and selecting a cadence never enables disabled email',()=>insightScenario(async s=>{
  const current=(await s.api('GET','/notification-preferences?orgId='+s.org.id)).data.preferences;
  assert.equal(current.digestFrequency,'manual');assert.equal(current.digestSchedule.nextRunAt,null);
  seed(s,1);assert.equal(runDueDigests(s.server.ctx,'2099-01-01T00:00:00.000Z').considered,0);
  await enable(s,{emailEnabled:false});
  assert.equal(preferences(s.server.ctx,s.user.id,s.org.id).digestSchedule.status,'disabled');
  assert.equal(runDueDigests(s.server.ctx,'2099-01-01T00:00:00.000Z').considered,0);
  assert.equal((await s.api('POST','/digests',{orgId:s.org.id})).status,409);
  assert.equal(digests(s.server.ctx).length,0);
}));
test('HTTP cadence validates all choices and denies missing token scopes and other organizations',()=>insightScenario(async s=>{
  for(const [frequency,ms] of [['manual',0],['15-minute',900000],['hourly',3600000],['daily',86400000]]) {
    const before=Date.now(),result=await s.api('PATCH','/notification-preferences',{orgId:s.org.id,digestFrequency:frequency});
    assert.equal(result.status,200);assert.equal(result.data.preferences.digestFrequency,frequency);
    const next=result.data.preferences.digestSchedule.nextRunAt;
    if(ms)assert(Date.parse(next)>=before+ms&&Date.parse(next)<=Date.now()+ms);else assert.equal(next,null);
  }
  for(const value of ['weekly',true,15,null])assert.equal((await s.api('PATCH','/notification-preferences',{orgId:s.org.id,digestFrequency:value})).status,422);
  assert.equal((await s.api('PATCH','/notification-preferences',{orgId:'other-org',digestFrequency:'daily'})).status,403);
  for(const scopes of [['insight:read','org:read'],['insight:write'],['org:read']]) {
    const token=(await s.api('POST','/tokens',{name:'Cadence limited',scopes})).data.token;
    const r=await s.api('PATCH','/notification-preferences',{orgId:s.org.id,digestFrequency:'hourly'},{authorization:'Bearer '+token});
    assert.equal(r.status,403);
  }
  const token=(await s.api('POST','/tokens',{name:'Cadence allowed',scopes:['insight:write','insight:read','org:read']})).data.token;
  assert.equal((await s.api('PATCH','/notification-preferences',{orgId:s.org.id,digestFrequency:'hourly'},{authorization:'Bearer '+token})).status,200);
  assert.equal((await s.api('GET','/notification-preferences?orgId=other-org',undefined,{authorization:'Bearer '+token})).status,403);
}));
test('automatic due boundary queues canonical content once and preserves unread state',()=>insightScenario(async s=>{
  seed(s,2);const due=await enable(s);
  assert.equal(runDueDigests(s.server.ctx,plus(due,-1)).considered,0);
  const result=runDueDigests(s.server.ctx,due);assert.equal(result.outcomes[0].count,2);
  assert.equal(runDueDigests(s.server.ctx,due).considered,0);
  const rows=digests(s.server.ctx);assert.equal(rows.length,1);
  const payload=JSON.parse(rows[0].payload_json);assert.equal(payload.notificationIds.length,2);
  assert.match(rows[0].text_body,/Digest row/);assert(rows[0].text_body.includes('\n'));
  const inbox=(await s.api('GET','/notifications?orgId='+s.org.id)).data;assert.equal(inbox.unread,2);
  assert.equal(s.server.ctx.db.prepare('SELECT count(*) n FROM notifications WHERE user_id=? AND digested_at=? AND read_at IS NULL').get(s.user.id,due).n,2);
  const pref=preferences(s.server.ctx,s.user.id,s.org.id);assert.equal(pref.digestSchedule.lastRunAt,due);assert.equal(pref.digestSchedule.nextRunAt,plus(due,900000));
}));
test('manual and automatic batches share duplicate exclusion in both execution orders',()=>insightScenario(async s=>{
  seed(s,2);const oldDue=await enable(s);
  assert.equal((await s.api('POST','/digests',{orgId:s.org.id})).data.count,2);
  assert.equal(runDueDigests(s.server.ctx,oldDue).outcomes.reduce((n,r)=>n+r.count,0),0);
  seed(s,1);const due=preferences(s.server.ctx,s.user.id,s.org.id).digestSchedule.nextRunAt;
  assert.equal(runDueDigests(s.server.ctx,due).outcomes[0].count,1);
  assert.equal((await s.api('POST','/digests',{orgId:s.org.id})).data.count,0);
  const ids=digests(s.server.ctx).flatMap(row=>JSON.parse(row.payload_json).notificationIds);
  assert.equal(ids.length,3);assert.equal(new Set(ids).size,3);
}));
test('current mentions-only preference filters notifications that existed before preference change',()=>insightScenario(async s=>{
  seed(s,1);seed(s,1,{reason:'mention'});const due=await enable(s,{mentionsOnly:true});
  const result=runDueDigests(s.server.ctx,due).outcomes[0];assert.equal(result.count,1);assert.equal(result.remaining,0);
  assert.equal(result.digest.items[0].reason,'mention');
  assert.equal(s.server.ctx.db.prepare('SELECT count(*) n FROM notifications WHERE user_id=? AND digested_at IS NULL').get(s.user.id).n,1);
}));
test('automatic selection rechecks guest grants and both relation endpoints immediately',()=>insightScenario(async s=>{
  const hidden=(await s.api('POST','/orgs/'+s.org.id+'/projects',{key:'SECRET',name:'Hidden'})).data.project;
  const issue=(await s.api('POST','/projects/'+hidden.id+'/issues',{title:'Revoked endpoint'})).data.issue;
  seed(s,1,{userId:s.memberUser.id,projectId:hidden.id});
  seed(s,1,{userId:s.memberUser.id,relation:{sourceIssueId:s.issue.id,targetIssueId:issue.id}});
  const due=(await s.member('PATCH','/notification-preferences',{orgId:s.org.id,digestFrequency:'15-minute'})).data.preferences.digestSchedule.nextRunAt;
  await s.api('PATCH','/orgs/'+s.org.id+'/members/'+s.memberUser.id,{role:'guest'});
  await s.api('POST','/projects/'+s.project.id+'/guests',{userId:s.memberUser.id});
  const result=runDueDigests(s.server.ctx,due).outcomes[0];
  assert.equal(result.count,1);assert(result.digest.items.every(item=>item.projectId===s.project.id&&item.activity.entityType!=='relation'));
  assert(!JSON.stringify(result).includes('Revoked endpoint'));
  const stored=(await s.member('GET','/digests?orgId='+s.org.id)).data.items;
  assert.equal(stored[0].count,1);
  await s.api('DELETE','/projects/'+s.project.id+'/guests/'+s.memberUser.id);
  assert.equal((await s.member('GET','/digests?orgId='+s.org.id)).data.items[0].count,0);
}));
test('revoked organization membership suspends due work without exposing or spinning on it',()=>insightScenario(async s=>{
  const due=(await s.member('PATCH','/notification-preferences',{orgId:s.org.id,digestFrequency:'15-minute'})).data.preferences.digestSchedule.nextRunAt;
  await s.api('DELETE','/orgs/'+s.org.id+'/members/'+s.memberUser.id);
  const result=runDueDigests(s.server.ctx,due);assert.equal(result.outcomes[0].skipped,true);
  const row=s.server.ctx.db.prepare('SELECT * FROM notification_preferences WHERE user_id=? AND org_id=?').get(s.memberUser.id,s.org.id);
  assert.equal(row.digest_status,'access-lost');assert.equal(row.digest_next_at,null);
  assert.equal(runDueDigests(s.server.ctx,plus(due,86400000)).considered,0);assert.equal(digests(s.server.ctx).length,0);
}));
test('451 eligible updates drain in bounded sequential batches with persisted honest backlog',()=>insightScenario(async s=>{
  seed(s,451);let due=await enable(s);
  for(const [count,remaining] of [[200,251],[200,51],[51,0]]) {
    assert.equal(runDueDigests(s.server.ctx,plus(due,-1)).considered,0);
    const batch=runDueDigests(s.server.ctx,due).outcomes[0];assert.equal(batch.count,count);assert.equal(batch.remaining,remaining);
    const schedule=preferences(s.server.ctx,s.user.id,s.org.id).digestSchedule;
    assert.equal(schedule.remaining,remaining);assert.equal(schedule.status,remaining?'backlog':'scheduled');
    assert.equal(schedule.nextRunAt,plus(due,remaining?15000:900000));due=schedule.nextRunAt;
  }
  const ids=digests(s.server.ctx).flatMap(row=>JSON.parse(row.payload_json).notificationIds);
  assert.equal(ids.length,451);assert.equal(new Set(ids).size,451);
  assert.equal((await s.api('GET','/notifications?orgId='+s.org.id)).data.unread,451);
}));
test('due state survives an actual app database close and fresh context restart',()=>insightScenario(async s=>{
  seed(s,201);const due=await enable(s);
  runDueDigests(s.server.ctx,due);
  const before=preferences(s.server.ctx,s.user.id,s.org.id).digestSchedule;
  s.server.ctx.close();
  const reopened=await createApp({dataDir:s.server.ctx.config.dataDir,secret:'test-secret'});
  try {
    assert.deepEqual(preferences(reopened,s.user.id,s.org.id).digestSchedule,before);
    assert.equal(runDueDigests(reopened,plus(before.nextRunAt,-1)).considered,0);
    assert.equal(runDueDigests(reopened,before.nextRunAt).outcomes[0].count,1);
    assert.equal(digests(reopened).length,2);
  } finally {reopened.close();}
}));
test('queue errors roll back content and markers then persist suspension without replay',()=>insightScenario(async s=>{
  seed(s,2);const due=await enable(s),original=s.server.ctx.enqueueOutbox;let calls=0;
  s.server.ctx.enqueueOutbox=input=>{calls++;original(input);throw new Error('injected after insert');};
  const result=runDueDigests(s.server.ctx,due);assert.equal(result.outcomes[0].status,'error');
  assert.equal(digests(s.server.ctx).length,0);
  assert.equal(s.server.ctx.db.prepare('SELECT count(*) n FROM notifications WHERE user_id=? AND digested_at IS NOT NULL').get(s.user.id).n,0);
  assert.equal(preferences(s.server.ctx,s.user.id,s.org.id).digestSchedule.status,'error');
  runDueDigests(s.server.ctx,plus(due,86400000));assert.equal(calls,1);
  await s.api('PATCH','/notification-preferences',{orgId:s.org.id,mentionsOnly:false});
  runDueDigests(s.server.ctx,plus(due,86400000));assert.equal(calls,1);
  s.server.ctx.enqueueOutbox=original;
  const next=await enable(s);assert.equal(runDueDigests(s.server.ctx,next).outcomes[0].count,2);
}));
test('due admission limits each pass to twenty scopes and later passes reach remaining scopes',()=>insightScenario(async s=>{
  let last;
  for(let n=0;n<21;n++) {
    const org=n===0?s.org:(await s.api('POST','/orgs',{name:'Cadence '+n})).data.organization;
    const result=await s.api('PATCH','/notification-preferences',{orgId:org.id,digestFrequency:'hourly'});
    last=result.data.preferences.digestSchedule.nextRunAt;
  }
  assert.equal(runDueDigests(s.server.ctx,last).considered,20);
  const final=runDueDigests(s.server.ctx,last);assert.equal(final.considered,1);assert.equal(final.outcomes[0].count,0);
  assert.equal(runDueDigests(s.server.ctx,last).considered,0);
}));
test('service skips overlapping ticks and cleanup prevents every later tick',async()=>{
  let callback,cleared=0,resolve,calls=0;
  const pending=new Promise(done=>resolve=done),ctx={now:()=>new Date().toISOString(),cleanups:[]};
  const service=startDigestService(ctx,{run:()=>{calls++;return pending;},setTimer:fn=>{callback=fn;return 7;},clearTimer:id=>{assert.equal(id,7);cleared++;}});
  const first=service.tick();assert.equal(await service.tick(),false);callback();assert.equal(calls,1);
  ctx.cleanups[0]();resolve();assert.equal(await first,true);assert.equal(service.state.status,'stopped');
  callback();assert.equal(await service.tick(),false);assert.equal(calls,1);assert.equal(cleared,1);
});
test('service error custody clears timer and prevents automatic failed-operation replay',async()=>{
  let calls=0,callback,cleared=0;
  const ctx={now:()=>new Date().toISOString()};
  const service=startDigestService(ctx,{run:()=>{calls++;throw new Error('uncertain database failure');},setTimer:fn=>{callback=fn;return 8;},clearTimer:()=>cleared++});
  assert.equal(await service.tick(),false);assert.equal(service.state.status,'error');assert.match(service.state.lastError,/review/);
  callback();assert.equal(await service.tick(),false);assert.equal(calls,1);assert.equal(cleared,1);
  service.stop();assert.equal(service.state.status,'error');
});
